stat, clear, span = chain.stat, chain.clear, chain.span
TABLES = {"RUN": RUN, "GATE": GATE, "SCALE": SCALE, "PROBE": PROBE}


def cell(table, row, draw):
    """A run's cell for each of the five networks, seed 1 first."""
    return TABLES[table][row + (draw,)]


def each(table, row, i, seeds=range(1, SEEDS + 1)):
    """A figure of a row's runs, network by network and then draw by draw, of the seeds given."""
    return [cell(table, row, d)[s - 1][i] for s in seeds for d in DRAWS]


def stand_in(table, row, draw):
    """The stand-in reference network's cell of the same row, draw and seed, for each of the five: the
    files before this one's."""
    if table == "SCALE":
        return scl.SCALE[MNIST][REFERENCE][row + (draw,)]
    return scl.cells(table, MNIST, REFERENCE, row, draw)


def mean(xs):
    return sum(xs) / len(xs)


def fig(row, seeds):
    """A row over its runs of the seeds given, as the harness prints it: the tile's accuracy and the
    class the declared reference's, percent; the rms error over the reference's rms, over the largest the
    reference is, and the largest over that, percent; the scale; the rms with it, percent; all means; and
    the runs at 99.5% on the class and within 1.0%, 1.0% and 2.0% on the three."""
    acc, cls = each("RUN", row, ACC, seeds), each("RUN", row, CLASS, seeds)
    x, y, z = ([100 * v for v in each("GATE", row, i, seeds)] for i in (RMS, RMSFS, MAXFS))
    s, w = each("SCALE", row, SC, seeds), [100 * v for v in each("SCALE", row, SC_RMS, seeds)]
    return (mean(acc), mean(cls), mean(x), mean(y), mean(z), mean(s), mean(w), sum(c >= GATE_CLASS for c in cls),
            sum(v <= GATE_RMS for v in x), sum(v <= GATE_RMS for v in y), sum(v <= GATE_MAX for v in z))


# a figure of a run, of the canary's cells and of the stand-in's: (table, place, times)
WHAT = {"acc": ("RUN", ACC, 1), "class": ("RUN", CLASS, 1), "rms": ("GATE", RMS, 100), "rmsfs": ("GATE", RMSFS, 100),
        "maxfs": ("GATE", MAXFS, 100), "scale": ("SCALE", SC, 1), "srms": ("SCALE", SC_RMS, 100)}


def per_net(what, row, theirs=False):
    """A figure for each of the five networks, a mean over the draws: the canary's, or the stand-in's."""
    table, i, k = WHAT[what]
    get = stand_in if theirs else cell
    return [k * mean([get(table, row, d)[n][i] for d in DRAWS]) for n in range(SEEDS)]


def against(what, row):
    """The canary's networks less the stand-in's of the same seeds, a row's figure: mean and standard error."""
    return stat([a - b for a, b in zip(per_net(what, row), per_net(what, row, True))])


def canary(what, row):
    """Seed 1's figure, a mean over its draws."""
    return per_net(what, row)[CANARY - 1]


def label(row):
    return NAME[row[:2]] + (", a thousand" if row[2] == FEW else "")


def section(title):
    print(f"\n{title}\n{'-' * len(title)}")


def main():
    print("The first board's canary, trained and run.")
    print("MNIST pooled to 8 x 8; FC1 and FC2 the host's at eight bits, FC3 trained for the tile at six; seed 1 the canary.")
    section("1. The networks: held out and digital, percent, and the noise on the last layer's sums, of their rms")
    for sd in range(1, SEEDS + 1):
        h, dg, nz = NETS[sd]
        print(f"    seed {sd}{', the canary' if sd == CANARY else '':<13} {h:>7.2f} {dg:>7.2f} {nz:>8.4f}")
    heads = f"    {'':<40}{'acc':>7}{'class':>7}{'rms':>7}{'rmsfs':>7}{'max':>7}{'scale':>9}{'srms':>7}{'cl':>4}{'rms':>4}{'fs':>4}{'max':>4}"
    for title, seeds in (("2. The canary, seed 1, over its five draws", (CANARY,)), ("3. The five networks over their 25 runs", range(1, SEEDS + 1))):
        section(title)
        print(heads)
        for row in ROWS:
            f = fig(row, seeds)
            print(f"    {label(row):<40}" + "".join(f"{v:>7.2f}" for v in f[:5]) + f"{f[5]:>9.5f}{f[6]:>7.2f}" + "".join(f"{v:>4d}" for v in f[7:]))
    section("4. Against the stand-in: the five networks less the stand-in reference networks of the same seeds, a mean and its error")
    print(f"    {'':<40}" + "".join(f"{w:>15}" for w in ("acc", "class", "rms", "rmsfs", "max", "scale")))
    for row in ROWS:
        print(f"    {label(row):<40}" + "".join(f"{against(w, row)[0]:>+8.3f} {against(w, row)[1]:>5.3f}"
                                               for w in ("acc", "class", "rms", "rmsfs", "maxfs", "scale")))
    said = io.StringIO()
    with contextlib.redirect_stdout(said):
        findings()
    print(said.getvalue(), end="")
    checks(" ".join(said.getvalue().split()))


def five(what, row):
    """The five networks' mean, a row's figure."""
    return mean(per_net(what, row))


def theirs(what, row):
    """The stand-in's five, a row's figure."""
    return mean(per_net(what, row, True))


def clear_rows(what):
    """The rows in which the canary's five differ from the stand-in's outside chance."""
    return [row for row in ROWS if clear(against(what, row))]


def pair(x, digits=3):
    return f"{x[0]:+.{digits}f} +-{x[1]:.{digits}f}"


