def findings():
    digital = [float(NETS[s][1]) for s in range(1, SEEDS + 1)]
    held = [float(NETS[s][0]) for s in range(1, SEEDS + 1)]
    noise = [float(NETS[s][2]) for s in range(1, SEEDS + 1)]
    acc_clear = clear_rows("acc")
    rms_clear = clear_rows("rms") + clear_rows("rmsfs") + clear_rows("maxfs")
    cls_clear = clear_rows("class")
    sc_gap = max(abs(against("scale", r)[0]) for r in ROWS)
    all5 = range(1, SEEDS + 1)
    print()
    print("What this says, six readings.  All of it is a stand-in classifier's, in a model.")
    print()
    print("  1. THE CANARY TRAINS AS B20 SAYS.  Each network was trained from its seed's 8-bit one for eight epochs, with")
    print(f"     noise of {min(noise):.4f} to {max(noise):.4f} of their rms on the last layer's sums and none on the first two layers'.")
    print(f"     On the host the five are {min(digital):.2f} to {max(digital):.2f}% right on the test images and {min(held):.2f} to {max(held):.2f}% on the")
    print(f"     held-out ones; the canary, seed 1, is {float(NETS[CANARY][1]):.2f}%.")
    print()
    print("  2. AT THE GATE THE CANARY IS THE STAND-IN.  Network for network, the canary's five less the stand-in's of the")
    print(f"     same seeds: the rms error over the reference's rms is {pair(against('rms', B_ALL))} as budgeted on 10,000 images,")
    print(f"     {pair(against('rms', B_FEW))} on the gate's thousand, and {pair(against('rms', LF_FEW))} lit and fitted on it.  No difference of")
    print(f"     rms, of rms over the largest the reference is, or of the largest error is clear in any row ({len(rms_clear)} of 30).  The")
    print(f"     scale is the stand-in's to {sc_gap:.4f}.  So the stand-in's figures at the gate on MNIST stand for the canary's.")
    print()
    print(f"  3. THE CANARY, SEED 1.  As budgeted, {canary('rms', B_ALL):.2f}% of the reference's rms on 10,000 images and {canary('rms', B_FEW):.2f}% on the gate's")
    print(f"     thousand, where the five are {five('rms', B_ALL):.2f} and {five('rms', B_FEW):.2f}; lit and fitted on the thousand, {canary('rms', LF_FEW):.2f} where the")
    print(f"     five are {five('rms', LF_FEW):.2f}.  Its class is the declared reference's on {canary('class', B_FEW):.2f}% of the gate's thousand as")
    print(f"     budgeted, at 99.5% in {fig(B_FEW, (CANARY,))[7]} of its 5 draws, and on {canary('class', LF_FEW):.2f}% lit and fitted, in {fig(LF_FEW, (CANARY,))[7]} of 5.")
    print()
    print("  4. WHAT IT GIVES UP IS A TENTH OF A POINT.  On 10,000 images the canary's five are right on the tile")
    fa, la, lc = against('acc', F_ALL), against('acc', ROW('budget', LITFIT)), against('class', L_ALL)
    print(f"     {-fa[0]:.2f} +-{fa[1]:.2f} of a point less often than the stand-in's with the format alone, and {-la[0]:.2f} +-{la[1]:.2f} lit and")
    print(f"     fitted: clear in {len(acc_clear)} of the 10 rows.  Lit, their class is the declared reference's {-lc[0]:.2f} +-{lc[1]:.2f} of a point")
    print(f"     less often, clear in {len(cls_clear)}.  On the gate's thousand no difference of accuracy or class is clear.")
    print()
    print("  5. NOT TO THE GATE'S 1.0%.  No run of the 25 is within 1.0% of the reference's rms in any row with the tile's")
    print(f"     budget in it, and all {fig(F_ALL, all5)[8]} are with the format alone.  Lit and fitted on the gate's thousand the largest error is")
    print(f"     {five('maxfs', LF_FEW):.2f}% of the largest the reference is, a mean, and no run of the {25 * len(TILED)} in a row with the budget is")
    print(f"     within 2.0%.")
    print()
    print("  6. WHAT THESE RUNS DO NOT SAY.  The canary is trained and run, not frozen: no golden tensor exists, and")
    print("     whether FC3's declared reference is the sum before the 8-bit converter, as here, or the converter's codes")
    print("     is not settled.  Its first two layers run on the host, exactly, at eight bits: B20's contract, and not a")
    print("     GRX930 NPU's or a G100's output.  And the canary's own figures are over five draws of one network.")
    print()
    got = predictions()
    print(f"What it was predicted to say.  Ten, written before any canary network was trained: {sum(ok for _, _, ok in got)} right.")
    for n, what, ok in got:
        print(f"  {n}. {'right' if ok else 'WRONG'}: {what}")


def checks(said):
    """Every claim above, as an assert.  `said` is the readings as printed, on one line."""
    all5 = range(1, SEEDS + 1)
    keys = {r + (d,) for r in ROWS for d in DRAWS}
    assert set(RUN) == set(GATE) == set(SCALE) == set(PROBE) == keys and len(keys) == 50
    assert all(len(TABLES[t][k]) == SEEDS for t in TABLES for k in keys)
    assert set(NETS) == set(PRINTED_NETS) == set(all5) and set(PRINTED_CANARY) == set(PRINTED_FIVE) == set(ROWS)

    def eq(got, want):
        assert got == want, (got, want)

    def same(g, p, tol):
        return abs(g - p) < tol

    # 0. The figures are grx930's: the three tables its harness printed, every cell, from the runs' own.
    count = 0
    for sd in all5:
        eq(PRINTED_NETS[sd], NETS[sd])
        count += 3
    for row in ROWS:
        for printed, seeds in ((PRINTED_CANARY, (CANARY,)), (PRINTED_FIVE, all5)):
            f, p = fig(row, seeds), printed[row]
            assert len(p) == 11, row
            assert same(f[0], p[0], 0.0051) and same(f[1], p[1], 0.0051), (row, seeds, f, p)
            assert all(same(f[i], p[i], 0.00051) for i in (2, 3, 4, 6)), (row, seeds, f, p)
            assert same(f[5], p[5], 0.0000051) and list(f[7:]) == list(p[7:]), (row, seeds, f, p)
            count += 11
    assert count == 15 + 220

    # Each run is what its row says: right on more than half, its class the reference's on more than
    # half, an error at all and its rms over the largest no more than its largest; a scale between a half
    # and one and a half, within a hundredth of the test images' own, and that one leaving no more than
    # either; and the format alone, with nothing drawn, the same run on every draw.
    for row in ROWS:
        for d in DRAWS:
            for n in range(SEEDS):
                r, g, s = cell("RUN", row, d)[n], cell("GATE", row, d)[n], cell("SCALE", row, d)[n]
                assert 50 < r[ACC] <= 100 and 50 < r[CLASS] <= 100 and 0 < g[RMS] and 0 < g[RMSFS] <= g[MAXFS], (row, d, n)
                assert 0.5 < s[SC] < 1.5 and abs(s[SC] - s[BEST]) <= 0.01, (row, d, n)
                assert s[BEST_RMS] <= g[RMS] + 0.00001 and s[BEST_RMS] <= s[SC_RMS] + 0.00001, (row, d, n)
        if row[0] == "format":
            assert all(cell(t, row, d) == cell(t, row, 0) for t in TABLES for d in DRAWS), row
    #    And the training: noise on the last layer alone, every network.
    assert all(0.095 < float(NETS[s][2]) < 0.105 for s in all5)

    # 1. The readings' figures.
    R = ROWS
    eq([round(canary("rms", r), 3) for r in R], [0.744, 4.542, 4.542, 5.042, 5.042, 0.783, 4.609, 4.609, 5.094, 5.094])
    eq([round(five("rms", r), 3) for r in R], [0.723, 4.471, 4.653, 5.298, 5.451, 0.753, 4.525, 4.525, 5.341, 5.341])
    eq([round(theirs("rms", r), 3) for r in R], [0.71, 4.463, 4.638, 5.179, 5.332, 0.738, 4.518, 4.518, 5.224, 5.224])
    eq([tuple(round(x, 3) for x in against("rms", r)) for r in R],
       [(0.013, 0.007), (0.007, 0.015), (0.015, 0.018), (0.119, 0.05), (0.119, 0.051), (0.015, 0.007), (0.007, 0.016),
        (0.007, 0.016), (0.117, 0.048), (0.117, 0.048)])
    eq([round(canary("class", r), 2) for r in R], [99.84, 99.6, 99.6, 99.4, 99.4, 99.9, 99.74, 99.74, 99.42, 99.42])
    eq([label(r) for r in clear_rows("acc")], ["format only", "as budgeted, fitted", "as budgeted, lit", "as budgeted, lit, fitted"])
    eq([label(r) for r in clear_rows("class")], ["as budgeted, lit", "as budgeted, lit, fitted"])
    eq(clear_rows("rms") + clear_rows("rmsfs") + clear_rows("maxfs"), [])
    #    every difference of accuracy that is clear is a loss, and none on the gate's thousand
    assert all(against("acc", r)[0] < 0 and r[2] == ALL for r in clear_rows("acc") + clear_rows("class"))
    assert 0.0018 < max(abs(against("scale", r)[0]) for r in R) < 0.0019
    eq([fig(r, all5)[8] for r in R], [25, 0, 0, 0, 0, 25, 0, 0, 0, 0])
    eq(sum(fig(r, all5)[10] for r in R if r[0] == "budget"), 0)

    # 2. The predictions: all ten right.
    got = predictions()
    eq([n for n, _, ok in got if ok], list(range(1, 11)))

    # 3. And the readings say those figures, each in its place.
    for words in (
        "noise of 0.0999 to 0.1001 of their rms on the last layer's sums and none on the first two layers'.",
        "On the host the five are 96.76 to 97.16% right on the test images and 97.17 to 97.57% on the held-out ones; the canary, seed 1, is 96.84%.",
        "the rms error over the reference's rms is +0.007 +-0.015 as budgeted on 10,000 images, +0.007 +-0.016 on the gate's thousand, and +0.117 +-0.048 lit and fitted on it.",
        "is clear in any row (0 of 30).",
        "scale is the stand-in's to 0.0019.",
        "As budgeted, 4.54% of the reference's rms on 10,000 images and 4.61% on the gate's thousand, where the five are 4.47 and 4.53; lit and fitted on the thousand, 5.09 where the five are 5.34.",
        "Its class is the declared reference's on 99.74% of the gate's thousand as budgeted, at 99.5% in 5 of its 5 draws, and on 99.42% lit and fitted, in 2 of 5.",
        "0.10 +-0.03 of a point less often than the stand-in's with the format alone, and 0.12 +-0.03 lit and fitted: clear in 4 of the 10 rows.",
        "Lit, their class is the declared reference's 0.05 +-0.02 of a point less often, clear in 2.",
        "and all 25 are with the format alone.",
        "10.48% of the largest the reference is, a mean, and no run of the 200 in a row with the budget is within 2.0%.",
        "Ten, written before any canary network was trained: 10 right.",
    ):
        assert said.count(words) == 1, words
    assert said.count(" right: ") == 10 and " WRONG: " not in said

    print()
    print("All checks pass.")


if __name__ == "__main__":
    main()
